T.Translations("deDE", {
  -- Modules/QoL/AddonButtons.lua
  ["Addon"] = "Addon",
  ["No addon buttons on the minimap."] = "Keine Addon-Buttons an der Minikarte.",
  ["Addon buttons"] = "Addon-Buttons",
  ["%d on the minimap. Click to list them."] = "%d an der Minikarte. Klicken für die Liste.",
  ["Addon buttons in a list"] = "Addon-Buttons in einer Liste",
  ["Hides the buttons addons put round the minimap; click the moon (day and night) at the minimap's edge to list them, and click one in the list to use it."] = "Versteckt die Buttons, die Addons um die Minikarte legen; klick auf den Mond (Tag und Nacht) am Rand der Minikarte, um sie aufzulisten, und klick einen in der Liste an, um ihn zu benutzen.",
  -- Modules/QoL/CooldownNumbers.lua
  ["Numbers on cooldowns"] = "Zahlen auf Abklingzeiten",
  ["The time left as a number on every action button and buff that is cooling down (the game's own countdown). With the restyle on, the numbers are in your theme's font. Switching it off gives back the game setting you had before."] = "Die Restzeit als Zahl auf jedem Aktionsbutton und Stärkungszauber, der gerade abklingt (der Countdown des Spiels). Mit eingeschaltetem Umgestalten stehen die Zahlen in der Schrift deines Themas. Ausschalten stellt deine vorherige Spieleinstellung wieder her.",
  -- Modules/QoL/FutureSpells.lua
  ["Future spells"] = "Künftige Zauber",
  ["Rank %d"] = "Rang %d",
  ["1 spell"] = "1 Zauber",
  ["%d spells"] = "%d Zauber",
  ["price not seen yet"] = "Preis noch unbekannt",
  ["%s + %d not seen yet"] = "%s + %d noch unbekannt",
  ["Learn now: %s for %s"] = "Jetzt lernen: %s für %s",
  ["Nothing new to learn at your level."] = "Auf deiner Stufe gibt es nichts Neues zu lernen.",
  ["Next, at level %d: %s for %s"] = "Als Nächstes, auf Stufe %d: %s für %s",
  ["Everything to level %d: %s for %s%s"] = "Alles bis Stufe %d: %s für %s%s",
  [" (you have %s)"] = " (du hast %s)",
  ["Levels from the game's own data. Visit your class trainer once and Codex notes what each spell costs."] = "Stufen aus den Daten des Spiels. Besuch einmal deinen Klassenlehrer, dann merkt sich Codex, was jeder Zauber kostet.",
  ["Prices as your class trainer asked them %s ago."] = "Preise, wie dein Klassenlehrer sie vor %s verlangt hat.",
  ["a while"] = "einiger Zeit",
  ["Level %d · %s"] = "Stufe %d · %s",
  ["Level %d  ·  learn now"] = "Stufe %d  ·  jetzt lernen",
  ["Level %d"] = "Stufe %d",
  ["You know every spell your class learns."] = "Du kennst jeden Zauber deiner Klasse.",
  ["Spells you haven't learned yet, by level, with their prices."] = "Zauber, die du noch nicht gelernt hast, nach Stufe, mit ihren Preisen.",
  ["Future spells in the spellbook"] = "Künftige Zauber im Zauberbuch",
  ["A tab after the spellbook's school tabs: every spell and rank your class learns that you haven't learned yet, by level, with what your class trainer asks for it, and what it all adds up to (what you can learn now, at the next level, and everything). Codex notes the prices when you visit your class trainer (shared by your characters of the same class); until then the list shows the spells without prices."] = "Ein Reiter hinter den Schulen-Reitern des Zauberbuchs: jeder Zauber und Rang deiner Klasse, den du noch nicht gelernt hast, nach Stufe, mit dem Preis deines Klassenlehrers und der Summe (was du jetzt lernen kannst, auf der nächsten Stufe und alles). Codex merkt sich die Preise, wenn du deinen Klassenlehrer besuchst (geteilt mit deinen Charakteren derselben Klasse); bis dahin zeigt die Liste die Zauber ohne Preise.",
  -- Modules/QoL/Gather.lua
  ["Gathering skill in tooltips"] = "Sammelfertigkeit in Tooltips",
  ["Herbs and ore show the Herbalism or Mining skill they need, on the node and on the minimap (\"Mithril Deposit (175)\"), coloured from your own skill: red = too low, then orange, yellow, green, grey."] = "Kräuter und Erze zeigen die nötige Fertigkeit in Kräuterkunde oder Bergbau, am Vorkommen und auf der Minikarte (\"Mithrilablagerung (175)\"), gefärbt nach deiner Fertigkeit: rot = zu niedrig, dann orange, gelb, grün, grau.",
  -- Modules/QoL/GreyOut.lua
  ["Grey out what you can't use"] = "Unbenutzbares ausgrauen",
  ["Action buttons you can't use right now (out of range, not enough mana, rage or energy, or not usable) turn grey, and the key text keeps its colour instead of turning red."] = "Aktionsbuttons, die du gerade nicht benutzen kannst (außer Reichweite, zu wenig Mana, Wut oder Energie oder nicht benutzbar), werden grau, und der Tastentext behält seine Farbe, statt rot zu werden.",
  -- Modules/QoL/GroupWhisper.lua
  ["Sent"] = "Gesendet",
  ["Whisper"] = "Flüstern",
  ["Whisper##button"] = "Flüstern",
  ["Write your message first: Chat page, \"Whisper group leaders\"."] = "Schreib zuerst deine Nachricht: Seite Chat, \"Gruppenleiter anflüstern\".",
  ["This group's leader can't be whispered right now."] = "Der Leiter dieser Gruppe kann gerade nicht angeflüstert werden.",
  ["Whisper the leader"] = "Leiter anflüstern",
  ["Sends %s: %s"] = "Sendet an %s: %s",
  ["the leader"] = "den Leiter",
  ["Write your message on the Chat page first (Whisper group leaders)."] = "Schreib zuerst deine Nachricht auf der Seite Chat (Gruppenleiter anflüstern).",
  ["Message"] = "Nachricht",
  ["Each group in the Looking For Group window has a Whisper button that sends this to its leader."] = "Jede Gruppe im Fenster der Gruppensuche hat einen Flüstern-Button, der dies an ihren Leiter sendet.",
  ["Write the message the Whisper button sends, e.g. \"Hi, 60 mage LF Scholo, can I join?\""] = "Schreib die Nachricht, die der Flüstern-Button sendet, z. B. \"Hi, Magier 60 sucht Scholo, darf ich mit?\"",
  ["Whisper group leaders"] = "Gruppenleiter anflüstern",
  ["A Whisper button on every group in the Looking For Group window: one click sends the group's leader your message. The same leader can be whispered again after two minutes."] = "Ein Flüstern-Button an jeder Gruppe im Fenster der Gruppensuche: Ein Klick sendet dem Gruppenleiter deine Nachricht. Denselben Leiter kannst du nach zwei Minuten wieder anflüstern.",
  -- Modules/QoL/HideEmpty.lua
  ["Hide empty slots"] = "Leere Plätze ausblenden",
  ["Action bar slots with nothing in them are hidden. They show again while you drag a spell or item, while Edit Mode is open and while you bind keys by hovering, so there is always somewhere to put it."] = "Leere Plätze der Aktionsleisten werden ausgeblendet. Sie erscheinen wieder, während du einen Zauber oder Gegenstand ziehst, der Bearbeitungsmodus offen ist und du Tasten per Mauszeiger belegst, damit immer Platz zum Ablegen ist.",
  -- Modules/QoL/HoverBind.lua
  ["No key yet: press one."] = "Noch keine Taste: drück eine.",
  ["Press another key to add it, Escape to clear."] = "Drück eine weitere Taste zum Hinzufügen, Escape zum Löschen.",
  ["Binding keys"] = "Tasten belegen",
  ["Point at an action button and press a key. Escape clears the button's keys."] = "Zeig auf einen Aktionsbutton und drück eine Taste. Escape löscht die Tasten des Buttons.",
  ["Done"] = "Fertig",
  ["Cancel"] = "Abbrechen",
  ["Bind keys by hovering is off: switch it on under Action bars > Buttons."] = "Tastenbelegung per Mauszeiger ist aus: schalte sie unter Aktionsleisten > Buttons ein.",
  ["Key binding waits until the fight is over."] = "Die Tastenbelegung wartet, bis der Kampf vorbei ist.",
  ["Key bindings saved."] = "Tastenbelegung gespeichert.",
  ["Key bindings put back."] = "Tastenbelegung zurückgesetzt.",
  ["Bind keys by hovering"] = "Tasten per Mauszeiger belegen",
  ["Point at an action button and press a key to bind it, Escape to clear it. Start it with the button below or /codex bind; Done saves the keys, Cancel puts back the ones you had. Not in a fight."] = "Zeig auf einen Aktionsbutton und drück eine Taste, um sie zu belegen, Escape löscht sie. Starte es mit dem Button unten oder /codex bind; Fertig speichert die Tasten, Abbrechen stellt die alten wieder her. Nicht im Kampf.",
  ["Start binding"] = "Belegen starten",
