  ["Quest"] = "Quest",
  ["Starts a quest"] = "Startet eine Quest",
  ["Mobs and items your quests need show the quest and your progress (\"Witherbark Scalper slain: 3/10\"); bag items that start a quest say so."] = "Gegner und Gegenstände, die deine Quests brauchen, zeigen die Quest und deinen Fortschritt (\"Skalpjäger der Bleichborken getötet: 3/10\"); Gegenstände in Taschen, die eine Quest starten, sagen es.",
  -- Modules/QoL/Ranks.lua
  ["its new rank"] = "den neuen Rang",
  ["Updated %s to %s on 1 button."] = "%s auf %s aktualisiert, auf 1 Button.",
  ["Updated %s to %s on %d buttons."] = "%s auf %s aktualisiert, auf %d Buttons.",
  ["Your action bars get their new ranks after the fight."] = "Deine Aktionsleisten bekommen die neuen Ränge nach dem Kampf.",
  ["Your action bars get their new ranks once your cursor is empty."] = "Deine Aktionsleisten bekommen die neuen Ränge, sobald dein Mauszeiger leer ist.",
  ["Your action bars already have the highest ranks you know."] = "Deine Aktionsleisten haben schon die höchsten Ränge, die du kennst.",
  ["Put new spell ranks on your action bars"] = "Neue Zauberränge auf die Aktionsleisten",
  ["When you learn a higher rank of a spell, your action buttons with a lower rank of it get the new one (after the fight if you are in one). A lower rank kept beside a higher one is left alone (for downranking), and so is a button where you put a lower rank back yourself. Macros and items are never touched."] = "Lernst du einen höheren Rang eines Zaubers, bekommen deine Aktionsbuttons mit einem niedrigeren Rang den neuen (nach dem Kampf, falls du in einem bist). Ein niedriger Rang neben einem höheren bleibt unberührt (zum Downranken), ebenso ein Button, auf den du selbst einen niedrigeren Rang zurückgelegt hast. Makros und Gegenstände werden nie angefasst.",
  ["Update now"] = "Jetzt aktualisieren",
