  ["Right-click: options. Right-drag: move it (out of combat)."] = "Rechtsklick: Optionen. Rechts ziehen: verschieben (außerhalb des Kampfes).",
  ["The skull key can only be changed out of combat."] = "Die Totenkopf-Taste lässt sich nur außerhalb des Kampfes ändern.",
  ["Key"] = "Taste",
