  ["%d tracked quests in 1 zone."] = "%d verfolgte Quests in 1 Gebiet.",
  ["%d tracked quests in %d zones."] = "%d verfolgte Quests in %d Gebieten.",
  ["Codex quest tracker"] = "Codex-Questverfolgung",
  ["Codex's own quest tracker shows your tracked quests under a heading per zone, the zone you're in first, the nearest quest first. Click a zone to fold it. Click a quest to open it in the quest log, Shift-click to stop tracking it, right-click for more. Quest items have their own button. Move it while Edit Mode is open (right-click its handle to put it back). Switching it on or off takes a reload."] = "Codex' eigene Questverfolgung zeigt deine verfolgten Quests unter einer Überschrift pro Gebiet, dein aktuelles Gebiet zuerst, die nächste Quest zuerst. Klick auf ein Gebiet klappt es ein. Klick auf eine Quest öffnet sie im Questlog, Shift-Klick beendet die Verfolgung, Rechtsklick zeigt mehr. Questgegenstände haben einen eigenen Button. Verschieben im Bearbeitungsmodus (Rechtsklick auf den Griff setzt sie zurück). Ein- oder Ausschalten braucht ein Neuladen.",
  ["Background"] = "Hintergrund",
  ["Fold the zones you aren't in"] = "Andere Gebiete einklappen",
  ["Show the game's tracker while it has other objectives"] = "Verfolgung des Spiels zeigen, solange sie andere Ziele hat",
  ["A dungeon scenario, a tracked recipe or achievement, bonus objectives: the game's tracker comes back for them (with your quests) and Codex's steps aside until they're gone."] = "Ein Dungeon-Szenario, ein verfolgtes Rezept oder Erfolg, Bonusziele: Die Verfolgung des Spiels kommt dafür zurück (mit deinen Quests), und die von Codex tritt zur Seite, bis sie weg sind.",
  ["Width"] = "Breite",
  ["Height"] = "Höhe",
  ["Game's: as tall as the game's own tracker (its Edit Mode height). Quests that don't fit scroll with the mouse wheel over the tracker, out of combat."] = "Spiel: so hoch wie die Verfolgung des Spiels (ihre Höhe im Bearbeitungsmodus). Quests, die nicht passen, scrollen mit dem Mausrad über der Verfolgung, außerhalb des Kampfes.",
  ["Put it back"] = "Zurücksetzen",
  ["Codex's own quest tracker: your quests under a heading per zone, the zone you're in first."] = "Codex' eigene Questverfolgung: deine Quests unter einer Überschrift pro Gebiet, dein aktuelles Gebiet zuerst.",
  -- Modules/QuestTracker/Window.lua
  ["Quest tracker"] = "Questverfolgung",
  ["Click: open in the quest log. Shift-click: stop tracking. Right-click: more."] = "Klick: im Questlog öffnen. Shift-Klick: nicht mehr verfolgen. Rechtsklick: mehr.",
  ["More above"] = "Mehr oben",
  ["More below"] = "Mehr unten",
  -- Modules/Highlight/Module.lua
  ["Small"] = "Klein",
  ["Large"] = "Groß",
  ["%d of %d highlights on."] = "%d von %d Hervorhebungen an.",
  ["Highlights"] = "Hervorhebungen",
  ["Rings on herbs, ore, chests and quest objects near you, \"!\" on quest mobs, glowing quest items in your bags."] = "Ringe um Kräuter, Erze, Truhen und Questobjekte in deiner Nähe, \"!\" auf Questgegnern, leuchtende Questgegenstände in deinen Taschen.",
  -- Modules/Highlight/Page.lua
  ["Herbs and ore"] = "Kräuter und Erze",
  ["A pulsing ring and the name on the herb or ore you are next to: herbs green, ore orange."] = "Ein pulsierender Ring und der Name am Kraut oder Erz neben dir: Kräuter grün, Erze orange.",
  ["Only for my gathering professions"] = "Nur für meine Sammelberufe",
  ["Herbs only with Herbalism, ore only with Mining."] = "Kräuter nur mit Kräuterkunde, Erze nur mit Bergbau.",
  ["Treasure chests"] = "Schatztruhen",
  ["Chests, footlockers and strongboxes, in gold."] = "Truhen, Schließkassetten und Geldkassetten, in Gold.",
  ["Fishing pools"] = "Fischschwärme",
  ["Schools of fish, floating wreckage and the like, in blue."] = "Fischschwärme, treibende Wrackteile und Ähnliches, in Blau.",
  ["Quest objects and quest mobs"] = "Questobjekte und Questgegner",
  ["A yellow ring and \"!\" on objects you need for a quest, a \"!\" over the nameplate of quest mobs (enemy nameplates must be on; skipped while Questie draws its own nameplate icons)."] = "Ein gelber Ring und \"!\" an Objekten, die du für eine Quest brauchst, ein \"!\" über der Namensplakette von Questgegnern (feindliche Namensplaketten müssen an sein; ausgelassen, solange Questie eigene Plakettensymbole zeichnet).",
  ["Quest items in bags"] = "Questgegenstände in Taschen",
  ["Quest items glow in Codex's bag window and the game's bags; a \"!\" marks items that start a quest."] = "Questgegenstände leuchten in Codex' Taschenfenster und den Taschen des Spiels; ein \"!\" markiert Gegenstände, die eine Quest starten.",
  ["Show the object's name"] = "Namen des Objekts zeigen",
  ["Under the ring, in the ring's colour."] = "Unter dem Ring, in der Farbe des Rings.",
  ["NodeSight is loaded, so Codex leaves this to it. Turn NodeSight off (or use Codex's copy: the button at the top of this section) to use these."] = "NodeSight ist geladen, also überlässt Codex ihm das. Schalte NodeSight aus (oder nutze Codex' Kopie: der Button oben in diesem Abschnitt), um diese zu verwenden.",
  ["Highlights are off: switch them on at the top of this section (then reload)."] = "Hervorhebungen sind aus: schalte sie oben in diesem Abschnitt ein (dann neu laden).",
  ["NodeSight is loaded too: both will mark the same objects."] = "NodeSight ist auch geladen: Beide markieren dieselben Objekte.",
  ["Ring size: %s"] = "Ringgröße: %s",
  ["Range: %d yards"] = "Reichweite: %d Meter",
  ["The game shows a nameplate for the object you would interact with (the nearest one in range, all round you). Codex turns that on while a herb, ore, chest, pool or quest object switch is on, puts its mark on it, and gives your own settings back when they are all off. Changes work at once."] = "Das Spiel zeigt eine Namensplakette für das Objekt, mit dem du interagieren würdest (das nächste in Reichweite, rundum). Codex schaltet das ein, solange ein Schalter für Kräuter, Erze, Truhen, Schwärme oder Questobjekte an ist, setzt seine Markierung darauf und stellt deine Einstellungen wieder her, wenn alle aus sind. Änderungen wirken sofort.",
  ["%d yards"] = "%d Meter",
  ["Range: how far away the game picks the object to show (the game may cap it)."] = "Reichweite: wie weit entfernt das Spiel das gezeigte Objekt wählt (das Spiel kann sie begrenzen).",
  -- Modules/Dialogue/Data.lua
  ["Ready"] = "Fertig",
  ["Daily"] = "Täglich",
  ["Repeatable"] = "Wiederholbar",
  ["Low level"] = "Niedrige Stufe",
  -- Modules/Dialogue/Gossip.lua
  ["Quests"] = "Quests",
  -- Modules/Dialogue/Module.lua
  ["A · Codex window"] = "A · Codex-Fenster",
  ["The game's window in the theme, sized to its content."] = "Das Fenster des Spiels im Thema, so groß wie sein Inhalt.",
  ["B · Subtitle bar"] = "B · Untertitelleiste",
  ["A bar at the bottom of the screen; the NPC stays in view."] = "Eine Leiste unten am Bildschirm; der NPC bleibt im Blick.",
  ["C · Book page"] = "C · Buchseite",
  ["A page at the side of the screen, like a storybook."] = "Eine Seite am Bildschirmrand, wie in einem Märchenbuch.",
  ["DialogueUI is loaded, so Codex leaves the NPC windows to it."] = "DialogueUI ist geladen, also überlässt Codex ihm die NPC-Fenster.",
  ["Off: the game's own quest and gossip windows."] = "Aus: die Quest- und Gesprächsfenster des Spiels.",
  ["Codex leaves the windows to the game; the quest options below still work."] = "Codex überlässt die Fenster dem Spiel; die Questoptionen unten funktionieren weiter.",
  ["On: %s."] = "An: %s.",
  ["On."] = "An.",
  ["Quest windows"] = "Questfenster",
  ["Quest and gossip windows in the Codex look, in three styles, with number keys and reputation rewards."] = "Quest- und Gesprächsfenster im Codex-Look, in drei Stilen, mit Zifferntasten und Rufbelohnungen.",
  -- Modules/Dialogue/Page.lua
  ["Show quest levels"] = "Queststufen zeigen",
  ["[48] before each quest name, in its difficulty colour."] = "[48] vor jedem Questnamen, in seiner Schwierigkeitsfarbe.",
  ["Write the text in as the game does"] = "Text einschreiben wie im Spiel",
  ["Off shows the whole text at once (the game's Instant Quest Text)."] = "Aus zeigt den ganzen Text auf einmal (Sofortiger Questtext des Spiels).",
  ["Stat Delta on rewards"] = "Stat Delta bei Belohnungen",
  ["Stat changes and the upgrade arrow on reward items, while the Stat Delta module is on."] = "Werteänderungen und der Verbesserungspfeil an Belohnungen, solange das Modul Stat Delta an ist.",
  ["Number keys pick choices"] = "Zifferntasten wählen",
  ["1 to 9 pick the rows in order, shown as small keys beside them. Space still accepts (Quest keys)."] = "1 bis 9 wählen die Zeilen der Reihe nach, als kleine Tasten daneben gezeigt. Leertaste nimmt weiter an (Questtasten).",
  ["Escape goes back to the list"] = "Escape geht zurück zur Liste",
  ["On a quest you opened from an NPC's list, Escape takes you back to the list instead of closing."] = "Bei einer Quest aus der Liste eines NPCs bringt dich Escape zur Liste zurück, statt zu schließen.",
  ["Tab picks the next reward"] = "Tab wählt die nächste Belohnung",
  ["When a quest lets you choose a reward."] = "Wenn du bei einer Quest eine Belohnung wählen kannst.",
  ["Open the only service at once"] = "Einzigen Dienst sofort öffnen",
  ["A banker, vendor, trainer or flight master with nothing else to say opens at once."] = "Ein Bankier, Händler, Lehrer oder Flugmeister ohne weiteren Text öffnet sofort.",
  ["Fade the game's interface"] = "Oberfläche des Spiels ausblenden",
  ["Styles B and C: bars, frames and chat fade out and come back when you walk away; never in a fight."] = "Stile B und C: Leisten, Rahmen und Chat blenden aus und kommen zurück, wenn du weggehst; nie im Kampf.",
  ["Accept quests by themselves"] = "Quests selbst annehmen",
  ["Not repeatable or grey (low level) quests, and not quests that ask first."] = "Keine wiederholbaren oder grauen (niedrigstufigen) Quests und keine, die erst nachfragen.",
  ["Hand in quests by themselves"] = "Quests selbst abgeben",
  ["Not repeatables, quests that take gold or marks, or when a reward must be chosen."] = "Keine wiederholbaren, keine, die Gold oder Marken kosten, und nicht, wenn eine Belohnung zu wählen ist.",
  ["Font size"] = "Schriftgröße",
  ["Medium"] = "Mittel",
  ["Medium##size"] = "Mittel",
  ["Window size"] = "Fenstergröße",
  ["DialogueUI is loaded, so Codex leaves the NPC windows to it (the switch at the top of this section can use Codex's instead)."] = "DialogueUI ist geladen, also überlässt Codex ihm die NPC-Fenster (der Schalter oben in diesem Abschnitt kann stattdessen Codex' nutzen).",
  ["DialogueUI is loaded too: both want to draw the NPC windows. Turn one of them off."] = "DialogueUI ist auch geladen: Beide wollen die NPC-Fenster zeichnen. Schalte eins davon aus.",
  ["Quest windows are off: switch them on at the top of this section (then reload)."] = "Questfenster sind aus: schalte sie oben in diesem Abschnitt ein (dann neu laden).",
  ["Quest and gossip windows"] = "Quest- und Gesprächsfenster",
  ["Codex draws the windows you get when you talk to an NPC: greeting, quests, rewards. Off keeps the game's own windows (the quest options below still work)."] = "Codex zeichnet die Fenster, die du beim Gespräch mit einem NPC bekommst: Begrüßung, Quests, Belohnungen. Aus behält die Fenster des Spiels (die Questoptionen unten funktionieren weiter).",
  ["Text"] = "Text",
  ["The game's own is 13."] = "Die des Spiels ist 13.",
  ["Styles A and C; the subtitle bar keeps its own width."] = "Stile A und C; die Untertitelleiste behält ihre Breite.",
  ["While talking"] = "Im Gespräch",
  ["Hold Shift while you talk to an NPC to talk normally: nothing is accepted, handed in or opened by itself."] = "Halte Shift beim Ansprechen eines NPCs, um normal zu reden: Nichts wird von selbst angenommen, abgegeben oder geöffnet.",
  -- Modules/Dialogue/Quest.lua
  ["experience"] = "Erfahrung",
  ["Learn"] = "Erlernen:",
  ["Costs"] = "Kosten:",
  ["Suggested players: %d"] = "Empfohlene Spieler: %d",
  ["Objectives"] = "Ziele",
  ["Rewards"] = "Belohnungen",
  ["Choose one when you hand it in:"] = "Wähle eine bei der Abgabe:",
  ["You will also receive:"] = "Du bekommst außerdem:",
  ["Bring"] = "Bring mit",
  ["Continue opens once you have everything."] = "Weiter geht, sobald du alles hast.",
  ["Choose your reward"] = "Wähle deine Belohnung",
  ["You will also receive"] = "Du bekommst außerdem",
  -- Modules/Dialogue/Window.lua
  ["Click the bar to read on"] = "Klick auf die Leiste zum Weiterlesen",
})

T.Translations("frFR", {
  -- Modules/QoL/AddonButtons.lua
  ["Addon"] = "Addon",
  ["No addon buttons on the minimap."] = "Aucun bouton d'addon sur la minicarte.",
  ["Addon buttons"] = "Boutons d'addons",
  ["%d on the minimap. Click to list them."] = "%d sur la minicarte. Cliquez pour les afficher.",
  ["Addon buttons in a list"] = "Boutons d'addons dans une liste",
  ["Hides the buttons addons put round the minimap; click the moon (day and night) at the minimap's edge to list them, and click one in the list to use it."] = "Cache les boutons que les addons placent autour de la minicarte ; cliquez sur la lune (jour et nuit) au bord de la minicarte pour les afficher, puis sur l'un d'eux dans la liste pour l'utiliser.",
  -- Modules/QoL/CooldownNumbers.lua
  ["Numbers on cooldowns"] = "Chiffres sur les temps de recharge",
  ["The time left as a number on every action button and buff that is cooling down (the game's own countdown). With the restyle on, the numbers are in your theme's font. Switching it off gives back the game setting you had before."] = "Le temps restant en chiffres sur chaque bouton d'action et amélioration en recharge (le décompte du jeu). Avec le nouveau style, les chiffres prennent la police de votre thème. Le désactiver rétablit votre ancien réglage du jeu.",
  -- Modules/QoL/FutureSpells.lua
  ["Future spells"] = "Sorts à venir",
  ["Rank %d"] = "Rang %d",
  ["1 spell"] = "1 sort",
  ["%d spells"] = "%d sorts",
  ["price not seen yet"] = "prix encore inconnu",
  ["%s + %d not seen yet"] = "%s + %d encore inconnus",
  ["Learn now: %s for %s"] = "À apprendre maintenant : %s pour %s",
  ["Nothing new to learn at your level."] = "Rien de nouveau à apprendre à votre niveau.",
  ["Next, at level %d: %s for %s"] = "Ensuite, au niveau %d : %s pour %s",
  ["Everything to level %d: %s for %s%s"] = "Tout jusqu'au niveau %d : %s pour %s%s",
  [" (you have %s)"] = " (vous avez %s)",
  ["Levels from the game's own data. Visit your class trainer once and Codex notes what each spell costs."] = "Niveaux tirés des données du jeu. Rendez visite une fois à votre maître de classe et Codex note le prix de chaque sort.",
  ["Prices as your class trainer asked them %s ago."] = "Prix demandés par votre maître de classe il y a %s.",
  ["a while"] = "un moment",
  ["Level %d · %s"] = "Niveau %d · %s",
  ["Level %d  ·  learn now"] = "Niveau %d  ·  à apprendre",
  ["Level %d"] = "Niveau %d",
  ["You know every spell your class learns."] = "Vous connaissez tous les sorts de votre classe.",
  ["Spells you haven't learned yet, by level, with their prices."] = "Les sorts que vous n'avez pas encore appris, par niveau, avec leur prix.",
  ["Future spells in the spellbook"] = "Sorts à venir dans le grimoire",
  ["A tab after the spellbook's school tabs: every spell and rank your class learns that you haven't learned yet, by level, with what your class trainer asks for it, and what it all adds up to (what you can learn now, at the next level, and everything). Codex notes the prices when you visit your class trainer (shared by your characters of the same class); until then the list shows the spells without prices."] = "Un onglet après les onglets d'écoles du grimoire : chaque sort et rang de votre classe pas encore appris, par niveau, avec le prix demandé par votre maître de classe et le total (ce que vous pouvez apprendre maintenant, au prochain niveau, et tout). Codex note les prix quand vous rendez visite à votre maître de classe (partagés entre vos personnages de la même classe) ; d'ici là, la liste montre les sorts sans prix.",
  -- Modules/QoL/Gather.lua
  ["Gathering skill in tooltips"] = "Compétence de récolte dans les infobulles",
  ["Herbs and ore show the Herbalism or Mining skill they need, on the node and on the minimap (\"Mithril Deposit (175)\"), coloured from your own skill: red = too low, then orange, yellow, green, grey."] = "Les herbes et minerais indiquent la compétence d'Herboristerie ou de Minage requise, sur le gisement et sur la minicarte (« Gisement de mithril (175) »), colorée selon votre compétence : rouge = trop basse, puis orange, jaune, vert, gris.",
  -- Modules/QoL/GreyOut.lua
  ["Grey out what you can't use"] = "Griser ce qui est inutilisable",
  ["Action buttons you can't use right now (out of range, not enough mana, rage or energy, or not usable) turn grey, and the key text keeps its colour instead of turning red."] = "Les boutons d'action inutilisables pour le moment (hors de portée, pas assez de mana, de rage ou d'énergie, ou inutilisables) deviennent gris, et le texte du raccourci garde sa couleur au lieu de virer au rouge.",
  -- Modules/QoL/GroupWhisper.lua
  ["Sent"] = "Envoyé",
  ["Whisper"] = "Chuchotement",
  ["Whisper##button"] = "Chuchoter",
  ["Write your message first: Chat page, \"Whisper group leaders\"."] = "Écrivez d'abord votre message : page Discussion, « Chuchoter aux chefs de groupe ».",
  ["This group's leader can't be whispered right now."] = "Impossible de chuchoter au chef de ce groupe pour le moment.",
  ["Whisper the leader"] = "Chuchoter au chef",
  ["Sends %s: %s"] = "Envoie à %s : %s",
  ["the leader"] = "le chef",
  ["Write your message on the Chat page first (Whisper group leaders)."] = "Écrivez d'abord votre message sur la page Discussion (Chuchoter aux chefs de groupe).",
  ["Message"] = "Message",
  ["Each group in the Looking For Group window has a Whisper button that sends this to its leader."] = "Chaque groupe de la fenêtre Recherche de groupe a un bouton Chuchoter qui envoie ceci à son chef.",
  ["Write the message the Whisper button sends, e.g. \"Hi, 60 mage LF Scholo, can I join?\""] = "Écrivez le message envoyé par le bouton Chuchoter, par ex. « Salut, mage 60 pour Scholo, je peux venir ? »",
  ["Whisper group leaders"] = "Chuchoter aux chefs de groupe",
  ["A Whisper button on every group in the Looking For Group window: one click sends the group's leader your message. The same leader can be whispered again after two minutes."] = "Un bouton Chuchoter sur chaque groupe de la fenêtre Recherche de groupe : un clic envoie votre message au chef du groupe. Vous pouvez rechuchoter au même chef après deux minutes.",
  -- Modules/QoL/HideEmpty.lua
  ["Hide empty slots"] = "Masquer les emplacements vides",
  ["Action bar slots with nothing in them are hidden. They show again while you drag a spell or item, while Edit Mode is open and while you bind keys by hovering, so there is always somewhere to put it."] = "Les emplacements vides des barres d'action sont masqués. Ils réapparaissent quand vous faites glisser un sort ou un objet, en mode Édition et pendant l'attribution des raccourcis au survol : il y a toujours une place où le poser.",
  -- Modules/QoL/HoverBind.lua
  ["No key yet: press one."] = "Aucune touche : appuyez sur une touche.",
  ["Press another key to add it, Escape to clear."] = "Appuyez sur une autre touche pour l'ajouter, Échap pour effacer.",
  ["Binding keys"] = "Attribution des touches",
  ["Point at an action button and press a key. Escape clears the button's keys."] = "Pointez un bouton d'action et appuyez sur une touche. Échap efface les touches du bouton.",
  ["Done"] = "Terminé",
  ["Cancel"] = "Annuler",
  ["Bind keys by hovering is off: switch it on under Action bars > Buttons."] = "Les raccourcis au survol sont désactivés : activez-les dans Barres d'action > Boutons.",
  ["Key binding waits until the fight is over."] = "L'attribution des touches attend la fin du combat.",
  ["Key bindings saved."] = "Raccourcis enregistrés.",
  ["Key bindings put back."] = "Raccourcis rétablis.",
  ["Bind keys by hovering"] = "Raccourcis au survol",
  ["Point at an action button and press a key to bind it, Escape to clear it. Start it with the button below or /codex bind; Done saves the keys, Cancel puts back the ones you had. Not in a fight."] = "Pointez un bouton d'action et appuyez sur une touche pour l'y lier, Échap pour l'effacer. Lancez-le avec le bouton ci-dessous ou /codex bind ; Terminé enregistre les touches, Annuler rétablit les anciennes. Pas en combat.",
  ["Start binding"] = "Lier des touches",
  -- Modules/QoL/Loot.lua
  ["Faster loot"] = "Butin plus rapide",
  ["With auto-loot, takes everything at once so the loot window barely flashes. Items that need a roll, a confirmation or a free bag slot stay in the window for you."] = "Avec le butin automatique, prend tout d'un coup : la fenêtre de butin ne fait que clignoter. Les objets qui demandent un jet de dés, une confirmation ou une place libre dans les sacs restent dans la fenêtre.",
  -- Modules/QoL/MapExtras.lua
