  ["%d of %d options on."] = "%d options sur %d activées.",
  ["Quality of life"] = "Confort",
  ["Small conveniences, each with its own switch: faster loot, quest and gathering info in tooltips, zone levels, unexplored areas, dungeons and town services on the map, glowing proc abilities, new spell ranks, numbers on cooldowns and key binding by hovering on your bars, a skull key for your role, a Whisper button for group leaders, and Learn all at trainers."] = "De petites commodités, chacune avec son interrupteur : butin plus rapide, infos de quête et de récolte dans les infobulles, niveaux des zones, zones inexplorées, donjons et services urbains sur la carte, techniques à proc lumineuses, nouveaux rangs de sorts, chiffres sur les recharges et raccourcis au survol sur vos barres, une touche crâne pour votre rôle, un bouton Chuchoter pour les chefs de groupe, et Tout apprendre chez les maîtres.",
  -- Modules/QoL/Page.lua
  ["%s is doing this, so Codex's %s stays idle. Turn it off there (or disable %s) to use Codex's."] = "%s s'en charge, donc « %s » de Codex reste inactif. Désactivez-le là-bas (ou désactivez %s) pour utiliser celui de Codex.",
  ["Proc glow"] = "Lueur des procs",
  ["Spell ranks"] = "Rangs des sorts",
  ["Learn all at trainers"] = "Tout apprendre chez les maîtres",
  ["Quest info in tooltips"] = "Infos de quête dans les infobulles",
  ["Quest tracker order"] = "Ordre du suivi des quêtes",
  ["Addon buttons on the minimap"] = "Boutons d'addons sur la minicarte",
  ["Reveal unexplored areas"] = "Révéler les zones inexplorées",
  ["Zone levels on the world map"] = "Niveaux des zones sur la carte du monde",
  ["Skull mark"] = "Crâne",
  ["other addon"] = "autre addon",
  ["Every small switch is off (General > Quality of life), so this one waits."] = "Toutes les petites options sont désactivées (Général > Confort de jeu), celle-ci attend donc.",
  ["Switch them on"] = "Les activer",
  ["Switched on: it starts after a reload."] = "Activé : démarre après un rechargement.",
  ["Small conveniences, each with its own switch on the page it belongs to. This switch turns all of them off at once."] = "De petites commodités, chacune avec son interrupteur sur sa page. Cet interrupteur les désactive toutes d'un coup.",
  ["Open"] = "Ouvrir",
  -- Modules/QoL/Quests.lua
  ["Quest"] = "Quête",
  ["Starts a quest"] = "Commence une quête",
  ["Mobs and items your quests need show the quest and your progress (\"Witherbark Scalper slain: 3/10\"); bag items that start a quest say so."] = "Les monstres et objets dont vos quêtes ont besoin affichent la quête et votre progression (« Scalpeur Fouette-bois tué : 3/10 ») ; les objets des sacs qui commencent une quête l'indiquent.",
  -- Modules/QoL/Ranks.lua
  ["its new rank"] = "son nouveau rang",
  ["Updated %s to %s on 1 button."] = "%s passé à %s sur 1 bouton.",
  ["Updated %s to %s on %d buttons."] = "%s passé à %s sur %d boutons.",
  ["Your action bars get their new ranks after the fight."] = "Vos barres d'action recevront leurs nouveaux rangs après le combat.",
  ["Your action bars get their new ranks once your cursor is empty."] = "Vos barres d'action recevront leurs nouveaux rangs quand votre curseur sera vide.",
  ["Your action bars already have the highest ranks you know."] = "Vos barres d'action ont déjà les plus hauts rangs que vous connaissez.",
  ["Put new spell ranks on your action bars"] = "Nouveaux rangs de sorts sur vos barres d'action",
  ["When you learn a higher rank of a spell, your action buttons with a lower rank of it get the new one (after the fight if you are in one). A lower rank kept beside a higher one is left alone (for downranking), and so is a button where you put a lower rank back yourself. Macros and items are never touched."] = "Quand vous apprenez un rang supérieur d'un sort, vos boutons d'action portant un rang inférieur reçoivent le nouveau (après le combat si vous êtes en combat). Un rang inférieur placé à côté d'un rang supérieur reste tel quel (pour lancer un rang plus bas), de même qu'un bouton où vous avez remis vous-même un rang inférieur. Les macros et objets ne sont jamais touchés.",
  ["Update now"] = "Mettre à jour",
  -- Modules/QoL/Reveal.lua
  ["Reveal unexplored areas on the map"] = "Révéler les zones inexplorées sur la carte",
  ["Zone maps show the parts you haven't explored yet too, instead of leaving them dark. Also on the small zone map."] = "Les cartes de zone montrent aussi les parties pas encore explorées au lieu de les laisser dans le noir. Aussi sur la petite carte de zone.",
  ["Tint unexplored areas"] = "Teinter les zones inexplorées",
  -- Modules/QoL/Skull.lua
  ["Tank"] = "Tank",
  ["Healer"] = "Soigneur",
  ["Damage"] = "Dégâts",
  ["Any role"] = "Tous les rôles",
  ["tank"] = "tank",
  ["healer"] = "soigneur",
  ["damage"] = "dégâts",
  ["Skull mark is off."] = "La marque crâne est désactivée.",
  ["Only in a group, and you are not in one."] = "Seulement en groupe, et vous n'êtes pas groupé.",
  ["You have no group role, and the skull is the %s's."] = "Vous n'avez pas de rôle de groupe, et le crâne est pour : %s.",
  ["Your role is %s; the skull is the %s's."] = "Votre rôle : %s ; le crâne est pour : %s.",
  ["No key"] = "Aucune touche",
  ["Click: the skull on your target."] = "Clic : le crâne sur votre cible.",
  ["Key: %s"] = "Touche : %s",
  ["Right-click: options. Right-drag: move it (out of combat)."] = "Clic droit : options. Glisser clic droit : déplacer (hors combat).",
  ["The skull key can only be changed out of combat."] = "La touche crâne ne se change que hors combat.",
  ["Key"] = "Touche",
  ["Press a key..."] = "Appuyez sur une touche...",
  ["Click, then press a key. Right-click to clear."] = "Cliquez, puis appuyez sur une touche. Clic droit pour effacer.",
  ["Not now: %s"] = "Pas maintenant : %s",
  ["Ready: your key and the button put the skull on your target."] = "Prêt : votre touche et le bouton mettent le crâne sur votre cible.",
  ["A key (and a button) that puts the skull on your target, only while your group role is the one the skull belongs to. The game doesn't let addons mark on their own, so it marks when you press the key: press it as you pull. It never takes the skull off."] = "Une touche (et un bouton) qui met le crâne sur votre cible, seulement si votre rôle de groupe est celui auquel revient le crâne. Le jeu ne laisse pas les addons marquer seuls, donc la marque se pose quand vous appuyez sur la touche : appuyez au moment du pull. Le crâne n'est jamais retiré.",
  ["Skull is for"] = "Crâne pour",
  ["Also when you have no group role"] = "Aussi sans rôle de groupe",
  ["Only in a party or raid"] = "Seulement en groupe ou en raid",
  ["Show the skull button"] = "Afficher le bouton crâne",
  ["Put the button back"] = "Replacer le bouton",
  -- Modules/QoL/TrackerSort.lua
  ["The quests of the zone you're in go to the top of the game's quest tracker, nearest first; the others follow grouped by zone. Sorted again when you change zone or subzone, and never in a fight. Codex's own quest tracker (Quest tracker module) sorts by itself."] = "Les quêtes de votre zone passent en haut du suivi des quêtes du jeu, la plus proche d'abord ; les autres suivent, groupées par zone. Retrié quand vous changez de zone ou de sous-zone, jamais en combat. Le suivi des quêtes de Codex (module Suivi des quêtes) trie de lui-même.",
  -- Modules/QoL/Trainer.lua
  ["Learned 1 spell for %s."] = "1 sort appris pour %s.",
  ["Learned %d spells for %s."] = "%d sorts appris pour %s.",
  ["Learn all (%d)"] = "Tout apprendre (%d)",
  ["Learn all"] = "Tout apprendre",
  ["1 spell for %s, cheapest first."] = "1 sort pour %s, le moins cher d'abord.",
  ["%d spells for %s, cheapest first."] = "%d sorts pour %s, les moins chers d'abord.",
  ["Nothing you can learn and afford right now."] = "Rien que vous puissiez apprendre et payer pour le moment.",
  ["%d more when you have the gold."] = "%d de plus quand vous aurez l'or.",
  ["Professions are left to you."] = "Les métiers restent à votre charge.",
  ["A Learn all button on the class trainer's window: learns every spell you can learn now and afford, cheapest first. Professions are left to you. Click again for spells whose lower rank you just learned."] = "Un bouton Tout apprendre dans la fenêtre du maître de classe : apprend chaque sort que vous pouvez apprendre et payer maintenant, le moins cher d'abord. Les métiers restent à votre charge. Recliquez pour les sorts dont vous venez d'apprendre le rang inférieur.",
  -- Modules/QoL/Zones.lua
  ["Hovering a zone on the map shows its level range (\"50-58\", coloured from your level) and, if you have them, the Fishing skill it needs and its Mining and Herbalism ranges. A zone map shows its own."] = "Survoler une zone sur la carte montre ses niveaux (« 50-58 », colorés selon votre niveau) et, si vous avez ces métiers, la compétence de Pêche requise et ses plages de Minage et d'Herboristerie. Une carte de zone montre les siens.",
  -- Modules/QuestKeys/Module.lua
  ["Off: Space jumps as usual."] = "Désactivé : Espace fait sauter comme d'habitude.",
  ["Space presses the quest button now."] = "Espace appuie maintenant sur le bouton de la quête.",
  ["Pick a reward first, then Space completes the quest."] = "Choisissez d'abord une récompense, puis Espace termine la quête.",
  ["Space presses the main button of Codex's quest window now."] = "Espace appuie maintenant sur le bouton principal de la fenêtre de quête de Codex.",
  ["On: Space picks quests from a quest giver's list and presses Complete Quest, Continue or Accept."] = "Activé : Espace choisit les quêtes dans la liste d'un donneur de quêtes et appuie sur Terminer la quête, Continuer ou Accepter.",
  ["Quest keys"] = "Touches de quête",
  ["While a quest giver's quest window is open, Space presses its main button, in this order: Complete Quest, Continue, Accept. When a quest giver lists quests (greeting or gossip window), Space picks one: a quest ready to turn in first, then the first new quest, then your other quests, in the order shown; press Space again to go on. When a quest offers several rewards, pick one first: Space waits until you do. During a fight Space jumps as usual, and typing in chat is never affected. Codex's own quest windows (the Quest windows module) follow these settings too."] = "Quand la fenêtre de quête d'un donneur de quêtes est ouverte, Espace appuie sur son bouton principal, dans cet ordre : Terminer la quête, Continuer, Accepter. Quand un donneur de quêtes liste des quêtes (fenêtre d'accueil ou de dialogue), Espace en choisit une : d'abord une quête prête à rendre, puis la première nouvelle quête, puis vos autres quêtes, dans l'ordre affiché ; appuyez de nouveau sur Espace pour continuer. Quand une quête offre plusieurs récompenses, choisissez-en une d'abord : Espace attend votre choix. En combat, Espace fait sauter comme d'habitude, et la saisie dans la discussion n'est jamais touchée. Les fenêtres de quête de Codex (module Fenêtres de quête) suivent aussi ces réglages.",
  ["Pick quests from greeting and gossip lists with Space"] = "Choisir les quêtes des listes d'accueil et de dialogue avec Espace",
  ["DialogueUI is loaded: it shows quests in its own window with its own keys, which may also use Space. Quest keys only works with the game's own quest window and Codex's."] = "DialogueUI est chargé : il affiche les quêtes dans sa propre fenêtre avec ses propres touches, qui peuvent aussi utiliser Espace. Touches de quête ne fonctionne qu'avec la fenêtre de quête du jeu et celle de Codex.",
  ["Space presses Complete Quest, Continue or Accept in the quest window."] = "Espace appuie sur Terminer la quête, Continuer ou Accepter dans la fenêtre de quête.",
  -- Modules/QuestTracker/Data.lua
  ["Here"] = "Ici",
  ["Other quests"] = "Autres quêtes",
  ["Quest %d"] = "Quête %d",
  -- Modules/QuestTracker/Module.lua
  ["Narrow"] = "Étroit",
  ["Normal"] = "Normal",
  ["Wide"] = "Large",
  ["Game's"] = "Du jeu",
  ["The quest log opens after the fight."] = "Le journal de quêtes s'ouvrira après le combat.",
  ["Off: the game's quest tracker is shown."] = "Désactivé : le suivi des quêtes du jeu est affiché.",
  ["Another addon has replaced the game's tracker, so Codex leaves the quests to it."] = "Un autre addon a remplacé le suivi du jeu, Codex lui laisse donc les quêtes.",
  ["The game's tracker is showing other objectives, so it shows your quests for now."] = "Le suivi du jeu affiche d'autres objectifs, il montre donc vos quêtes pour l'instant.",
  ["1 tracked quest in 1 zone."] = "1 quête suivie dans 1 zone.",
  ["1 tracked quest in %d zones."] = "1 quête suivie dans %d zones.",
  ["%d tracked quests in 1 zone."] = "%d quêtes suivies dans 1 zone.",
  ["%d tracked quests in %d zones."] = "%d quêtes suivies dans %d zones.",
  ["Codex quest tracker"] = "Suivi des quêtes Codex",
  ["Codex's own quest tracker shows your tracked quests under a heading per zone, the zone you're in first, the nearest quest first. Click a zone to fold it. Click a quest to open it in the quest log, Shift-click to stop tracking it, right-click for more. Quest items have their own button. Move it while Edit Mode is open (right-click its handle to put it back). Switching it on or off takes a reload."] = "Le suivi des quêtes de Codex montre vos quêtes suivies sous un titre par zone, votre zone d'abord, la quête la plus proche d'abord. Cliquez sur une zone pour la replier. Cliquez sur une quête pour l'ouvrir dans le journal, Maj-clic pour ne plus la suivre, clic droit pour plus d'options. Les objets de quête ont leur propre bouton. Déplacez-le en mode Édition (clic droit sur sa poignée pour le replacer). L'activer ou le désactiver demande un rechargement.",
  ["Background"] = "Fond",
  ["Fold the zones you aren't in"] = "Replier les zones où vous n'êtes pas",
  ["Show the game's tracker while it has other objectives"] = "Afficher le suivi du jeu quand il a d'autres objectifs",
  ["A dungeon scenario, a tracked recipe or achievement, bonus objectives: the game's tracker comes back for them (with your quests) and Codex's steps aside until they're gone."] = "Un scénario de donjon, une recette ou un haut fait suivi, des objectifs bonus : le suivi du jeu revient pour eux (avec vos quêtes) et celui de Codex s'efface jusqu'à ce qu'ils disparaissent.",
  ["Width"] = "Largeur",
  ["Height"] = "Hauteur",
  ["Game's: as tall as the game's own tracker (its Edit Mode height). Quests that don't fit scroll with the mouse wheel over the tracker, out of combat."] = "Du jeu : aussi haut que le suivi du jeu (sa hauteur en mode Édition). Les quêtes qui ne tiennent pas défilent avec la molette sur le suivi, hors combat.",
  ["Put it back"] = "Le replacer",
  ["Codex's own quest tracker: your quests under a heading per zone, the zone you're in first."] = "Le suivi des quêtes de Codex : vos quêtes sous un titre par zone, votre zone d'abord.",
  -- Modules/QuestTracker/Window.lua
  ["Quest tracker"] = "Suivi des quêtes",
  ["Click: open in the quest log. Shift-click: stop tracking. Right-click: more."] = "Clic : ouvrir dans le journal. Maj-clic : ne plus suivre. Clic droit : plus.",
  ["More above"] = "Plus haut",
  ["More below"] = "Plus bas",
  -- Modules/Highlight/Module.lua
  ["Small"] = "Petit",
  ["Large"] = "Grand",
  ["%d of %d highlights on."] = "%d surlignages sur %d activés.",
  ["Highlights"] = "Surbrillance",
  ["Rings on herbs, ore, chests and quest objects near you, \"!\" on quest mobs, glowing quest items in your bags."] = "Des anneaux sur les herbes, minerais, coffres et objets de quête proches, un « ! » sur les monstres de quête, des objets de quête lumineux dans vos sacs.",
  -- Modules/Highlight/Page.lua
  ["Herbs and ore"] = "Herbes et minerais",
  ["A pulsing ring and the name on the herb or ore you are next to: herbs green, ore orange."] = "Un anneau pulsant et le nom sur l'herbe ou le minerai près de vous : herbes en vert, minerais en orange.",
  ["Only for my gathering professions"] = "Seulement pour mes métiers de récolte",
  ["Herbs only with Herbalism, ore only with Mining."] = "Herbes seulement avec Herboristerie, minerais seulement avec Minage.",
  ["Treasure chests"] = "Coffres au trésor",
  ["Chests, footlockers and strongboxes, in gold."] = "Coffres, cantines et coffres-forts, en doré.",
  ["Fishing pools"] = "Bancs de pêche",
  ["Schools of fish, floating wreckage and the like, in blue."] = "Bancs de poissons, débris flottants et autres, en bleu.",
  ["Quest objects and quest mobs"] = "Objets et monstres de quête",
  ["A yellow ring and \"!\" on objects you need for a quest, a \"!\" over the nameplate of quest mobs (enemy nameplates must be on; skipped while Questie draws its own nameplate icons)."] = "Un anneau jaune et un « ! » sur les objets nécessaires à une quête, un « ! » au-dessus de la barre de nom des monstres de quête (barres de nom ennemies activées ; ignoré quand Questie dessine ses propres icônes).",
  ["Quest items in bags"] = "Objets de quête dans les sacs",
  ["Quest items glow in Codex's bag window and the game's bags; a \"!\" marks items that start a quest."] = "Les objets de quête brillent dans la fenêtre de sacs de Codex et les sacs du jeu ; un « ! » marque les objets qui commencent une quête.",
  ["Show the object's name"] = "Afficher le nom de l'objet",
  ["Under the ring, in the ring's colour."] = "Sous l'anneau, dans sa couleur.",
  ["NodeSight is loaded, so Codex leaves this to it. Turn NodeSight off (or use Codex's copy: the button at the top of this section) to use these."] = "NodeSight est chargé, Codex lui laisse donc ceci. Désactivez NodeSight (ou utilisez la copie de Codex : le bouton en haut de cette section) pour utiliser ces options.",
  ["Highlights are off: switch them on at the top of this section (then reload)."] = "Les surlignages sont désactivés : activez-les en haut de cette section (puis rechargez).",
  ["NodeSight is loaded too: both will mark the same objects."] = "NodeSight est aussi chargé : les deux marqueront les mêmes objets.",
  ["Ring size: %s"] = "Taille de l'anneau : %s",
  ["Range: %d yards"] = "Portée : %d mètres",
  ["The game shows a nameplate for the object you would interact with (the nearest one in range, all round you). Codex turns that on while a herb, ore, chest, pool or quest object switch is on, puts its mark on it, and gives your own settings back when they are all off. Changes work at once."] = "Le jeu affiche une barre de nom pour l'objet avec lequel vous interagiriez (le plus proche à portée, tout autour de vous). Codex l'active tant qu'une option herbe, minerai, coffre, banc ou objet de quête est active, y pose sa marque, et rétablit vos réglages quand elles sont toutes désactivées. Les changements s'appliquent aussitôt.",
  ["%d yards"] = "%d mètres",
  ["Range: how far away the game picks the object to show (the game may cap it)."] = "Portée : la distance jusqu'à laquelle le jeu choisit l'objet à montrer (le jeu peut la limiter).",
