  ["Quests"] = "Quêtes",
  -- Modules/Dialogue/Module.lua
  ["A · Codex window"] = "A · Fenêtre Codex",
  ["The game's window in the theme, sized to its content."] = "La fenêtre du jeu aux couleurs du thème, à la taille de son contenu.",
  ["B · Subtitle bar"] = "B · Barre de sous-titres",
  ["A bar at the bottom of the screen; the NPC stays in view."] = "Une barre en bas de l'écran ; le PNJ reste visible.",
  ["C · Book page"] = "C · Page de livre",
  ["A page at the side of the screen, like a storybook."] = "Une page sur le côté de l'écran, comme un livre de contes.",
  ["DialogueUI is loaded, so Codex leaves the NPC windows to it."] = "DialogueUI est chargé, Codex lui laisse donc les fenêtres des PNJ.",
  ["Off: the game's own quest and gossip windows."] = "Désactivé : les fenêtres de quête et de dialogue du jeu.",
  ["Codex leaves the windows to the game; the quest options below still work."] = "Codex laisse les fenêtres au jeu ; les options de quête ci-dessous fonctionnent toujours.",
  ["On: %s."] = "Activé : %s.",
  ["On."] = "Activé.",
  ["Quest windows"] = "Fenêtres de quête",
  ["Quest and gossip windows in the Codex look, in three styles, with number keys and reputation rewards."] = "Fenêtres de quête et de dialogue au style Codex, en trois styles, avec touches numériques et récompenses de réputation.",
  -- Modules/Dialogue/Page.lua
  ["Show quest levels"] = "Afficher le niveau des quêtes",
  ["[48] before each quest name, in its difficulty colour."] = "[48] devant chaque nom de quête, dans la couleur de sa difficulté.",
  ["Write the text in as the game does"] = "Écrire le texte comme le jeu",
  ["Off shows the whole text at once (the game's Instant Quest Text)."] = "Désactivé, tout le texte s'affiche d'un coup (le texte de quête instantané du jeu).",
  ["Stat Delta on rewards"] = "Stat Delta sur les récompenses",
  ["Stat changes and the upgrade arrow on reward items, while the Stat Delta module is on."] = "Variations de caractéristiques et flèche d'amélioration sur les objets en récompense, tant que le module Stat Delta est actif.",
  ["Number keys pick choices"] = "Touches numériques pour choisir",
  ["1 to 9 pick the rows in order, shown as small keys beside them. Space still accepts (Quest keys)."] = "1 à 9 choisissent les lignes dans l'ordre, affichées en petites touches à côté. Espace accepte toujours (Touches de quête).",
  ["Escape goes back to the list"] = "Échap revient à la liste",
  ["On a quest you opened from an NPC's list, Escape takes you back to the list instead of closing."] = "Sur une quête ouverte depuis la liste d'un PNJ, Échap revient à la liste au lieu de fermer.",
  ["Tab picks the next reward"] = "Tab choisit la récompense suivante",
  ["When a quest lets you choose a reward."] = "Quand une quête vous laisse choisir une récompense.",
  ["Open the only service at once"] = "Ouvrir directement le seul service",
  ["A banker, vendor, trainer or flight master with nothing else to say opens at once."] = "Un banquier, marchand, maître ou maître de vol sans rien d'autre à dire s'ouvre directement.",
  ["Fade the game's interface"] = "Estomper l'interface du jeu",
  ["Styles B and C: bars, frames and chat fade out and come back when you walk away; never in a fight."] = "Styles B et C : barres, cadres et discussion s'estompent et reviennent quand vous partez ; jamais en combat.",
  ["Accept quests by themselves"] = "Accepter les quêtes automatiquement",
  ["Not repeatable or grey (low level) quests, and not quests that ask first."] = "Pas les quêtes répétables ou grises (bas niveau), ni celles qui demandent confirmation.",
  ["Hand in quests by themselves"] = "Rendre les quêtes automatiquement",
  ["Not repeatables, quests that take gold or marks, or when a reward must be chosen."] = "Pas les répétables, les quêtes qui coûtent de l'or ou des marques, ni quand il faut choisir une récompense.",
  ["Font size"] = "Taille du texte",
  ["Medium"] = "Moyen",
  ["Medium##size"] = "Moyen",
  ["Window size"] = "Taille",
  ["DialogueUI is loaded, so Codex leaves the NPC windows to it (the switch at the top of this section can use Codex's instead)."] = "DialogueUI est chargé, Codex lui laisse donc les fenêtres des PNJ (l'interrupteur en haut de cette section permet d'utiliser celles de Codex).",
  ["DialogueUI is loaded too: both want to draw the NPC windows. Turn one of them off."] = "DialogueUI est aussi chargé : les deux veulent dessiner les fenêtres des PNJ. Désactivez l'un des deux.",
  ["Quest windows are off: switch them on at the top of this section (then reload)."] = "Les fenêtres de quête sont désactivées : activez-les en haut de cette section (puis rechargez).",
  ["Quest and gossip windows"] = "Fenêtres de quête et de dialogue",
  ["Codex draws the windows you get when you talk to an NPC: greeting, quests, rewards. Off keeps the game's own windows (the quest options below still work)."] = "Codex dessine les fenêtres qui s'ouvrent quand vous parlez à un PNJ : accueil, quêtes, récompenses. Désactivé, le jeu garde ses fenêtres (les options de quête ci-dessous fonctionnent toujours).",
