  ["You will also receive"] = "Vous recevrez aussi",
  -- Modules/Dialogue/Window.lua
  ["Click the bar to read on"] = "Cliquez sur la barre pour lire la suite",
})

T.Translations("esES", {
  -- Modules/QoL/AddonButtons.lua
  ["Addon"] = "Addon",
  ["No addon buttons on the minimap."] = "No hay botones de addons en el minimapa.",
  ["Addon buttons"] = "Botones de addons",
  ["%d on the minimap. Click to list them."] = "%d en el minimapa. Haz clic para verlos en una lista.",
  ["Addon buttons in a list"] = "Botones de addons en una lista",
  ["Hides the buttons addons put round the minimap; click the moon (day and night) at the minimap's edge to list them, and click one in the list to use it."] = "Oculta los botones que los addons ponen alrededor del minimapa; haz clic en la luna (día y noche) del borde del minimapa para verlos en una lista y haz clic en uno para usarlo.",
  -- Modules/QoL/CooldownNumbers.lua
  ["Numbers on cooldowns"] = "Números en los tiempos de reutilización",
  ["The time left as a number on every action button and buff that is cooling down (the game's own countdown). With the restyle on, the numbers are in your theme's font. Switching it off gives back the game setting you had before."] = "El tiempo restante como número en cada botón de acción y beneficio que se está recargando (la cuenta atrás del propio juego). Con el nuevo estilo activo, los números usan la fuente de tu tema. Al desactivarlo vuelve el ajuste del juego que tenías antes.",
  -- Modules/QoL/FutureSpells.lua
  ["Future spells"] = "Hechizos futuros",
  ["Rank %d"] = "Rango %d",
  ["1 spell"] = "1 hechizo",
  ["%d spells"] = "%d hechizos",
  ["price not seen yet"] = "precio aún no visto",
  ["%s + %d not seen yet"] = "%s + %d aún sin ver",
  ["Learn now: %s for %s"] = "Aprender ahora: %s por %s",
  ["Nothing new to learn at your level."] = "Nada nuevo que aprender a tu nivel.",
  ["Next, at level %d: %s for %s"] = "Después, a nivel %d: %s por %s",
  ["Everything to level %d: %s for %s%s"] = "Todo hasta nivel %d: %s por %s%s",
  [" (you have %s)"] = " (tienes %s)",
  ["Levels from the game's own data. Visit your class trainer once and Codex notes what each spell costs."] = "Niveles según los datos del propio juego. Visita una vez a tu instructor de clase y Codex anota lo que cuesta cada hechizo.",
  ["Prices as your class trainer asked them %s ago."] = "Precios que pedía tu instructor de clase hace %s.",
  ["a while"] = "un tiempo",
  ["Level %d · %s"] = "Nivel %d · %s",
  ["Level %d  ·  learn now"] = "Nivel %d  ·  aprender ahora",
  ["Level %d"] = "Nivel %d",
  ["You know every spell your class learns."] = "Conoces todos los hechizos que aprende tu clase.",
  ["Spells you haven't learned yet, by level, with their prices."] = "Hechizos que aún no has aprendido, por nivel, con sus precios.",
  ["Future spells in the spellbook"] = "Hechizos futuros en el libro de hechizos",
  ["A tab after the spellbook's school tabs: every spell and rank your class learns that you haven't learned yet, by level, with what your class trainer asks for it, and what it all adds up to (what you can learn now, at the next level, and everything). Codex notes the prices when you visit your class trainer (shared by your characters of the same class); until then the list shows the spells without prices."] = "Una pestaña tras las pestañas de escuelas del libro de hechizos: cada hechizo y rango de tu clase que aún no has aprendido, por nivel, con lo que pide tu instructor de clase y lo que suma todo (lo que puedes aprender ahora, en el siguiente nivel y en total). Codex anota los precios cuando visitas a tu instructor de clase (compartidos por tus personajes de la misma clase); hasta entonces la lista muestra los hechizos sin precio.",
  -- Modules/QoL/Gather.lua
  ["Gathering skill in tooltips"] = "Habilidad de recolección en descripciones",
  ["Herbs and ore show the Herbalism or Mining skill they need, on the node and on the minimap (\"Mithril Deposit (175)\"), coloured from your own skill: red = too low, then orange, yellow, green, grey."] = "Las hierbas y los minerales muestran la habilidad de Herboristería o Minería que piden, en el nodo y en el minimapa (\"Depósito de mitril (175)\"), con el color según tu habilidad: rojo = demasiado baja, luego naranja, amarillo, verde, gris.",
  -- Modules/QoL/GreyOut.lua
  ["Grey out what you can't use"] = "Atenuar lo que no puedes usar",
  ["Action buttons you can't use right now (out of range, not enough mana, rage or energy, or not usable) turn grey, and the key text keeps its colour instead of turning red."] = "Los botones de acción que no puedes usar ahora (fuera de alcance, sin maná, ira o energía suficientes, o no utilizables) se vuelven grises, y el texto de la tecla mantiene su color en vez de ponerse rojo.",
  -- Modules/QoL/GroupWhisper.lua
  ["Sent"] = "Enviado",
  ["Whisper"] = "Susurro",
  ["Whisper##button"] = "Susurrar",
  ["Write your message first: Chat page, \"Whisper group leaders\"."] = "Escribe primero tu mensaje: página Chat, \"Susurrar a líderes de grupo\".",
  ["This group's leader can't be whispered right now."] = "Ahora no se puede susurrar al líder de este grupo.",
  ["Whisper the leader"] = "Susurrar al líder",
  ["Sends %s: %s"] = "Envía a %s: %s",
  ["the leader"] = "el líder",
  ["Write your message on the Chat page first (Whisper group leaders)."] = "Escribe primero tu mensaje en la página Chat (Susurrar a líderes de grupo).",
  ["Message"] = "Mensaje",
  ["Each group in the Looking For Group window has a Whisper button that sends this to its leader."] = "Cada grupo de la ventana Buscar grupo tiene un botón Susurrar que envía esto a su líder.",
  ["Write the message the Whisper button sends, e.g. \"Hi, 60 mage LF Scholo, can I join?\""] = "Escribe el mensaje que envía el botón Susurrar, p. ej. \"Hola, mago 60 busca Scholo, ¿puedo unirme?\"",
  ["Whisper group leaders"] = "Susurrar a líderes de grupo",
  ["A Whisper button on every group in the Looking For Group window: one click sends the group's leader your message. The same leader can be whispered again after two minutes."] = "Un botón Susurrar en cada grupo de la ventana Buscar grupo: un clic envía tu mensaje al líder del grupo. Puedes volver a susurrar al mismo líder tras dos minutos.",
  -- Modules/QoL/HideEmpty.lua
  ["Hide empty slots"] = "Ocultar casillas vacías",
  ["Action bar slots with nothing in them are hidden. They show again while you drag a spell or item, while Edit Mode is open and while you bind keys by hovering, so there is always somewhere to put it."] = "Las casillas vacías de las barras de acción se ocultan. Vuelven a verse mientras arrastras un hechizo u objeto, con el Modo de edición abierto y mientras asignas teclas al pasar el ratón, así siempre hay dónde ponerlo.",
  -- Modules/QoL/HoverBind.lua
  ["No key yet: press one."] = "Aún sin tecla: pulsa una.",
  ["Press another key to add it, Escape to clear."] = "Pulsa otra tecla para añadirla, Escape para borrar.",
  ["Binding keys"] = "Asignando teclas",
  ["Point at an action button and press a key. Escape clears the button's keys."] = "Apunta a un botón de acción y pulsa una tecla. Escape borra las teclas del botón.",
  ["Done"] = "Listo",
  ["Cancel"] = "Cancelar",
  ["Bind keys by hovering is off: switch it on under Action bars > Buttons."] = "Asignar teclas al pasar el ratón está desactivado: actívalo en Barras de acción > Botones.",
  ["Key binding waits until the fight is over."] = "La asignación de teclas espera a que acabe el combate.",
  ["Key bindings saved."] = "Asignaciones de teclas guardadas.",
  ["Key bindings put back."] = "Asignaciones de teclas restauradas.",
  ["Bind keys by hovering"] = "Asignar teclas al pasar el ratón",
  ["Point at an action button and press a key to bind it, Escape to clear it. Start it with the button below or /codex bind; Done saves the keys, Cancel puts back the ones you had. Not in a fight."] = "Apunta a un botón de acción y pulsa una tecla para asignarla, Escape para borrarla. Empieza con el botón de abajo o /codex bind; Hecho guarda las teclas, Cancelar restaura las que tenías. No en combate.",
  ["Start binding"] = "Empezar a asignar",
  -- Modules/QoL/Loot.lua
  ["Faster loot"] = "Despojo más rápido",
  ["With auto-loot, takes everything at once so the loot window barely flashes. Items that need a roll, a confirmation or a free bag slot stay in the window for you."] = "Con el despojo automático, lo recoge todo de golpe y la ventana de botín apenas parpadea. Los objetos que piden tirada, confirmación o un hueco libre en la bolsa se quedan en la ventana para ti.",
  -- Modules/QoL/MapExtras.lua
