  ["%s shows %s, so Codex leaves those to it."] = "%s muestra %s, así que Codex se lo deja.",
  ["Raid, %d players"] = "Banda, %d jugadores",
  ["Dungeon, %d players"] = "Mazmorra, %d jugadores",
  ["Raid"] = "Banda",
