  ["Switch them on"] = "Ligá-los",
  ["Switched on: it starts after a reload."] = "Ligado: começa após recarregar.",
  ["Small conveniences, each with its own switch on the page it belongs to. This switch turns all of them off at once."] = "Pequenas comodidades, cada uma com seu interruptor na página a que pertence. Este interruptor desliga todas de uma vez.",
  ["Open"] = "Abrir",
  -- Modules/QoL/Quests.lua
  ["Quest"] = "Missão",
  ["Starts a quest"] = "Inicia uma missão",
  ["Mobs and items your quests need show the quest and your progress (\"Witherbark Scalper slain: 3/10\"); bag items that start a quest say so."] = "Criaturas e itens de que suas missões precisam mostram a missão e seu progresso (\"Escalpelador Casca-murcha morto: 3/10\"); itens da bolsa que iniciam uma missão avisam isso.",
  -- Modules/QoL/Ranks.lua
  ["its new rank"] = "seu novo grau",
  ["Updated %s to %s on 1 button."] = "%s atualizado para %s em 1 botão.",
  ["Updated %s to %s on %d buttons."] = "%s atualizado para %s em %d botões.",
  ["Your action bars get their new ranks after the fight."] = "Suas barras de ações recebem os novos graus após o combate.",
  ["Your action bars get their new ranks once your cursor is empty."] = "Suas barras de ações recebem os novos graus quando o cursor estiver vazio.",
  ["Your action bars already have the highest ranks you know."] = "Suas barras de ações já têm os graus mais altos que você conhece.",
  ["Put new spell ranks on your action bars"] = "Colocar novos graus de feitiço nas barras de ações",
  ["When you learn a higher rank of a spell, your action buttons with a lower rank of it get the new one (after the fight if you are in one). A lower rank kept beside a higher one is left alone (for downranking), and so is a button where you put a lower rank back yourself. Macros and items are never touched."] = "Quando você aprende um grau maior de um feitiço, seus botões de ação com um grau menor dele recebem o novo (após o combate, se estiver em um). Um grau menor mantido ao lado de um maior não é mexido (para usar graus menores), nem um botão onde você mesmo recolocou um grau menor. Macros e itens nunca são alterados.",
  ["Update now"] = "Atualizar agora",
