  ["Reveal unexplored areas on the map"] = "Revelar áreas inexploradas no mapa",
  ["Zone maps show the parts you haven't explored yet too, instead of leaving them dark. Also on the small zone map."] = "Os mapas de zona mostram também as partes que você ainda não explorou, em vez de deixá-las escuras. Também no minimapa de zona.",
  ["Tint unexplored areas"] = "Colorir áreas inexploradas",
  -- Modules/QoL/Skull.lua
  ["Tank"] = "Tanque",
  ["Healer"] = "Curador",
  ["Damage"] = "Dano",
  ["Any role"] = "Qualquer função",
