  ["Only in a group, and you are not in one."] = "Só em grupo, e você não está em um.",
  ["You have no group role, and the skull is the %s's."] = "Você não tem função no grupo, e a caveira é para: %s.",
  ["Your role is %s; the skull is the %s's."] = "Sua função: %s; a caveira é para: %s.",
  ["No key"] = "Sem tecla",
  ["Click: the skull on your target."] = "Clique: caveira no seu alvo.",
  ["Key: %s"] = "Tecla: %s",
