  ["%d of %d highlights on."] = "%d de %d destaques ligados.",
  ["Highlights"] = "Destaques",
  ["Rings on herbs, ore, chests and quest objects near you, \"!\" on quest mobs, glowing quest items in your bags."] = "Anéis em ervas, minérios, baús e objetos de missão perto de você, \"!\" em criaturas de missão, itens de missão brilhando nas bolsas.",
  -- Modules/Highlight/Page.lua
  ["Herbs and ore"] = "Ervas e minérios",
  ["A pulsing ring and the name on the herb or ore you are next to: herbs green, ore orange."] = "Um anel pulsante e o nome na erva ou minério ao seu lado: ervas em verde, minérios em laranja.",
  ["Only for my gathering professions"] = "Só para minhas profissões de coleta",
  ["Herbs only with Herbalism, ore only with Mining."] = "Ervas só com Herborismo, minérios só com Mineração.",
  ["Treasure chests"] = "Baús de tesouro",
  ["Chests, footlockers and strongboxes, in gold."] = "Baús, arcas e cofres, em dourado.",
  ["Fishing pools"] = "Cardumes",
  ["Schools of fish, floating wreckage and the like, in blue."] = "Cardumes, destroços flutuantes e afins, em azul.",
  ["Quest objects and quest mobs"] = "Objetos e criaturas de missão",
  ["A yellow ring and \"!\" on objects you need for a quest, a \"!\" over the nameplate of quest mobs (enemy nameplates must be on; skipped while Questie draws its own nameplate icons)."] = "Um anel amarelo e \"!\" nos objetos de que você precisa para uma missão, um \"!\" sobre a placa de nome das criaturas de missão (as placas de inimigos devem estar ligadas; ignorado enquanto o Questie desenha os próprios ícones).",
  ["Quest items in bags"] = "Itens de missão nas bolsas",
  ["Quest items glow in Codex's bag window and the game's bags; a \"!\" marks items that start a quest."] = "Itens de missão brilham na janela de bolsas do Codex e nas bolsas do jogo; um \"!\" marca itens que iniciam uma missão.",
  ["Show the object's name"] = "Mostrar o nome do objeto",
  ["Under the ring, in the ring's colour."] = "Sob o anel, na cor do anel.",
  ["NodeSight is loaded, so Codex leaves this to it. Turn NodeSight off (or use Codex's copy: the button at the top of this section) to use these."] = "NodeSight está carregado, então o Codex deixa isso com ele. Desligue o NodeSight (ou use a cópia do Codex: o botão no topo desta seção) para usar estes.",
  ["Highlights are off: switch them on at the top of this section (then reload)."] = "Os destaques estão desligados: ligue-os no topo desta seção (depois recarregue).",
  ["NodeSight is loaded too: both will mark the same objects."] = "NodeSight também está carregado: os dois vão marcar os mesmos objetos.",
  ["Ring size: %s"] = "Tamanho do anel: %s",
  ["Range: %d yards"] = "Alcance: %d metros",
  ["The game shows a nameplate for the object you would interact with (the nearest one in range, all round you). Codex turns that on while a herb, ore, chest, pool or quest object switch is on, puts its mark on it, and gives your own settings back when they are all off. Changes work at once."] = "O jogo mostra uma placa de nome para o objeto com que você interagiria (o mais próximo ao alcance, ao seu redor). O Codex liga isso enquanto algum interruptor de erva, minério, baú, cardume ou objeto de missão estiver ligado, põe a marca nele e devolve suas configurações quando todos estiverem desligados. As mudanças valem na hora.",
  ["%d yards"] = "%d metros",
  ["Range: how far away the game picks the object to show (the game may cap it)."] = "Alcance: a que distância o jogo escolhe o objeto a mostrar (o jogo pode limitar).",
