  ["Number keys pick choices"] = "Teclas numéricas escolhem",
  ["1 to 9 pick the rows in order, shown as small keys beside them. Space still accepts (Quest keys)."] = "1 a 9 escolhem as linhas em ordem, mostradas como pequenas teclas ao lado. Espaço ainda aceita (Teclas de missão).",
  ["Escape goes back to the list"] = "Esc volta para a lista",
  ["On a quest you opened from an NPC's list, Escape takes you back to the list instead of closing."] = "Em uma missão aberta da lista de um PNJ, Esc volta para a lista em vez de fechar.",
  ["Tab picks the next reward"] = "Tab escolhe a próxima recompensa",
  ["When a quest lets you choose a reward."] = "Quando uma missão deixa você escolher uma recompensa.",
  ["Open the only service at once"] = "Abrir o único serviço na hora",
  ["A banker, vendor, trainer or flight master with nothing else to say opens at once."] = "Um banqueiro, vendedor, instrutor ou mestre de voo sem mais nada a dizer abre na hora.",
  ["Fade the game's interface"] = "Esmaecer a interface do jogo",
  ["Styles B and C: bars, frames and chat fade out and come back when you walk away; never in a fight."] = "Estilos B e C: barras, quadros e bate-papo esmaecem e voltam quando você se afasta; nunca em combate.",
  ["Accept quests by themselves"] = "Aceitar missões sozinho",
  ["Not repeatable or grey (low level) quests, and not quests that ask first."] = "Não missões repetíveis ou cinza (nível baixo), nem missões que perguntam antes.",
  ["Hand in quests by themselves"] = "Entregar missões sozinho",
  ["Not repeatables, quests that take gold or marks, or when a reward must be chosen."] = "Não repetíveis, missões que cobram ouro ou insígnias, nem quando é preciso escolher uma recompensa.",
  ["Font size"] = "Tamanho da fonte",
